from typing import List

class Solution:
    def minSwaps(self, grid: List[List[int]]) -> int:
        n = len(grid)
        trailing = []
        for row in grid:
            k = 0
            for j in range(n - 1, -1, -1):
                if row[j] == 0:
                    k += 1
                else:
                    break
            trailing.append(k)

        ans = 0
        for i in range(n):
            need = n - 1 - i
            j = i
            while j < n and trailing[j] < need:
                j += 1
            if j == n:
                return -1
            while j > i:
                trailing[j] = trailing[j - 1]
                j -= 1
                ans += 1
        return ans

