import java.io.*;
import java.util.*;

class Solution {
    public int minSwaps(int[][] grid) {
        int n = grid.length;
        int[] trailing = new int[n];

        for (int i = 0; i < n; i++) {
            int k = 0;
            for (int j = n - 1; j >= 0 && grid[i][j] == 0; j--) k++;
            trailing[i] = k;
        }

        int ans = 0;
        for (int i = 0; i < n; i++) {
            int need = n - 1 - i;
            int j = i;
            while (j < n && trailing[j] < need) j++;
            if (j == n) return -1;
            while (j > i) {
                trailing[j] = trailing[j - 1];
                j--;
                ans++;
            }
        }
        return ans;
    }
}

