class Solution {
public:
    int minSwaps(vector<vector<int>>& grid) {
        int n = (int)grid.size();
        vector<int> trailing(n);

        for (int i = 0; i < n; ++i) {
            int k = 0;
            for (int j = n - 1; j >= 0 && grid[i][j] == 0; --j) ++k;
            trailing[i] = k;
        }

        int ans = 0;
        for (int i = 0; i < n; ++i) {
            int j = i;
            while (j < n && trailing[j] > i) ++j;
            if (j == n) return -1;
            while (j > i) {
                trailing[j] = trailing[j - 1];
                --j;
                ++ans;
            }
        }
        return ans;
    }
};

vector<string> splitTop(const string& s) {
    vector<string> parts;
    int depth = 0, start = 0;
    for (int i = 0; i < (int)s.size(); ++i) {
        if (s[i] == '[') ++depth;
        else if (s[i] == ']') --depth;
        else if (s[i] == ',' && depth == 0) {
            parts.push_back(s.substr(start, i - start));
            start = i + 1;
        }
    }
    parts.push_back(s.substr(start));
    return parts;
}

vector<int> parseRow(string s) {
    s = s.substr(1, s.size() - 2);
    vector<string> parts = splitTop(s);
    vector<int> row;
    for (string p : parts) {
        if (!p.empty()) row.push_back(stoi(p));
    }
    return row;
}

vector<vector<int>> parseGrid(string s) {
    s = s.substr(1, s.size() - 2);
    vector<string> rows = splitTop(s);
    vector<vector<int>> g;
    for (string row : rows) g.push_back(parseRow(row));
    return g;
}

