typedef struct {
    char *s;
    int pos;
    int len;
} Tok;

static void skipWS(Tok *t) {
    while (t->pos < t->len &&
           (t->s[t->pos] == ' ' || t->s[t->pos] == ',' ||
            t->s[t->pos] == '\t' || t->s[t->pos] == '\n' ||
            t->s[t->pos] == '\r')) {
        t->pos++;
    }
}

static char *nextToken(Tok *t) {
    skipWS(t);
    if (t->pos >= t->len) return NULL;

    int start = t->pos;
    if (t->s[t->pos] == '[') {
        int depth = 0;
        while (t->pos < t->len) {
            char c = t->s[t->pos++];
            if (c == '[') depth++;
            else if (c == ']') {
                depth--;
                if (depth == 0) break;
            }
        }
    } else {
        while (t->pos < t->len && t->s[t->pos] != ',' &&
               t->s[t->pos] != ']' && t->s[t->pos] != '[') {
            t->pos++;
        }
    }

    int len = t->pos - start;
    char *out = (char *)malloc((size_t)len + 1);
    memcpy(out, t->s + start, (size_t)len);
    out[len] = '\0';
    return out;
}

static int *parseRow(Tok *t, int *size) {
    char *tok = nextToken(t);
    if (!tok || strcmp(tok, "[]") == 0) {
        free(tok);
        *size = 0;
        return NULL;
    }

    int len = (int)strlen(tok);
    char *inner = (char *)malloc((size_t)len - 1);
    memcpy(inner, tok + 1, (size_t)len - 2);
    inner[len - 2] = '\0';
    free(tok);

    int count = 1;
    for (int i = 0; inner[i]; ++i)
        if (inner[i] == ',') ++count;

    int *row = (int *)malloc((size_t)count * sizeof(int));
    Tok t2 = {inner, 0, (int)strlen(inner)};
    for (int i = 0; i < count; ++i) {
        char *x = nextToken(&t2);
        row[i] = atoi(x);
        free(x);
    }
    free(inner);
    *size = count;
    return row;
}

static int **parseGrid(Tok *t, int *rows, int **cols) {
    char *tok = nextToken(t);
    if (!tok || strcmp(tok, "[]") == 0) {
        free(tok);
        *rows = 0;
        *cols = NULL;
        return NULL;
    }

    int len = (int)strlen(tok);
    char *inner = (char *)malloc((size_t)len - 1);
    memcpy(inner, tok + 1, (size_t)len - 2);
    inner[len - 2] = '\0';
    free(tok);

    int r = 0, depth = 0;
    for (int i = 0; inner[i]; ++i) {
        if (inner[i] == '[') {
            if (depth == 0) ++r;
            ++depth;
        } else if (inner[i] == ']') {
            --depth;
        }
    }

    int **grid = (int **)malloc((size_t)r * sizeof(int *));
    int *c = (int *)malloc((size_t)r * sizeof(int));
    Tok t2 = {inner, 0, (int)strlen(inner)};
    for (int i = 0; i < r; ++i)
        grid[i] = parseRow(&t2, &c[i]);

    free(inner);
    *rows = r;
    *cols = c;
    return grid;
}

int minSwaps(int **grid, int gridSize, int *gridColSize) {
    int n = gridSize;
    int *trailing = (int *)malloc((size_t)n * sizeof(int));

    for (int i = 0; i < n; ++i) {
        int k = 0;
        for (int j = n - 1; j >= 0 && grid[i][j] == 0; --j)
            ++k;
        trailing[i] = k;
    }

    int ans = 0;
    for (int i = 0; i < n; ++i) {
        int j = i;
        while (j < n && trailing[j] > i) ++j;
        if (j == n) {
            free(trailing);
            return -1;
        }
        while (j > i) {
            trailing[j] = trailing[j - 1];
            --j;
            ++ans;
        }
    }

    free(trailing);
    return ans;
}

